   stats: SessionLogStats,
   toolUsage: ToolUsageStats[] | null,
   timePeriods: TimePeriodStats[] | null,
   groupBy: "day" | "week" | null,
 ): void {
   // AC: @session-log-stats ac-1 - Totals
