2430	export async function computeToolUsageStats(
2431	  sessionsDir: string,
2432	  sessionIds: string[],
2433	  limit: number = 10,
2434	): Promise<ToolUsageStats[]> {
2435	  const toolCounts: Record<string, number> = {};
2436	  let totalToolCalls = 0;
