2439	    const eventsPath = getSessionEventsPath(sessionsDir, sessionId);
2440	    try {
2441	      const content = await fsPromises.readFile(eventsPath, "utf-8");
2442	      if (!content.trim()) continue;
2443	      const lines = content.trim().split("\n");
2444	      // Track seen toolCallIds to deduplicate phased events
2445	      const seenToolCallIds = new Set<string>();
2446	      for (const line of lines) {
2447	        // Quick pre-filter: only parse lines that might be tool_call events
2448	        if (!line.includes('"tool_call"')) continue;
2449	        try {
2450	          const event = JSON.parse(line);
2451	          if (event?.type === "session.update") {
2452	            const update = event?.data?.update;
2453	            if (update?.sessionUpdate === "tool_call") {
2454	              // Deduplicate phased tool_call events by toolCallId
2455	              const toolCallId = update?.toolCallId || update?.tool_call_id || update?.id;
2456	              if (toolCallId && seenToolCallIds.has(toolCallId)) continue;
2457	              if (toolCallId) seenToolCallIds.add(toolCallId);
2458	              const toolName = update?._meta?.claudeCode?.toolName || "unknown";
2459	              toolCounts[toolName] = (toolCounts[toolName] || 0) + 1;
2460	              totalToolCalls++;
2461	            }
2462	          }
2463	        } catch {
2464	          // Skip unparseable lines
2465	        }
2466	      }
2467	    } catch {
2468	      // Skip sessions without events
2469	    }
2470	  }
2471	
2472	  // Sort by count descending, take top N
2473	  const sorted = Object.entries(toolCounts)
2474	    .map(([tool_name, count]) => ({
2475	      tool_name,
2476	      count,
2477	      percentage: totalToolCalls > 0
2478	        ? Math.round((count / totalToolCalls) * 100 * 10) / 10
2479	        : 0,
2480	    }))
2481	    .sort((a, b) => b.count - a.count)
2482	    .slice(0, limit);
